import store

def reserve(name, seats, capacity):
    # Validate name is not blank
    if not name or not isinstance(name, str):
        raise ValueError("Name cannot be blank")

    # Validate seats is a positive integer
    if not isinstance(seats, int) or isinstance(seats, bool) or seats <= 0:
        raise ValueError("Seats must be a positive integer")

    # Validate capacity is a positive integer
    if not isinstance(capacity, int) or isinstance(capacity, bool) or capacity <= 0:
        raise ValueError("Capacity must be a positive integer")

    # Check for overflow (seats > capacity)
    if seats > capacity:
        raise ValueError("Seats cannot exceed capacity")

    # Store the reservation
    token = len(store.reservations) + 1
    store.reservations[token] = {'name': name, 'seats': seats, 'capacity': capacity}

    return token

def cancel(token):
    if token not in store.reservations:
        raise KeyError("Unknown token")
    del store.reservations[token]
